# Try a different interpretation: fence between first and last non-fill value

def apply_fence_v4(input_grid):
    """Fill between first and last unique values with 1s and 4 at unique"""
    result = [row[:] for row in input_grid]

    for r in range(len(input_grid)):
        row = input_grid[r]
        fill_val = 6

        # Find first non-fill value
        first_pos = next((c for c, v in enumerate(row) if v != fill_val), None)
        # Find last non-fill value
        last_pos = next((c for c in range(len(row)-1, -1, -1) if row[c] != fill_val), None)

        if first_pos is None or last_pos is None:
            continue

        # Fence region: between first and last, exclusive of first and last
        fence_start, fence_end = first_pos + 1, last_pos

        # Check if there's a unique value (not fill, not marker) inside fence
        # The unique value is the "special" one (8 in this case, not 9)
        unique_pos = None
        for c in range(first_pos + 1, fence_end):
            if row[c] != fill_val and row[c] not in (9,):  # Marker is 9
                unique_pos = c
                break

        # Apply fence to interior of first-last region
        if unique_pos is not None:
            for c in range(first_pos + 1, fence_end):
                if c == unique_pos:
                    result[r][c] = 4
                else:
                    result[r][c] = 1
        elif unique_pos is None:
            # No unique value -> still apply fence but all 1s
            for c in range(first_pos + 1, fence_end):
                result[r][c] = 1

        # Keep the markers
        for c in range(first_pos, fence_end):
            if row[c] == fill_val:
                result[r][c] = fill_val
            elif row[c] == fill_val:
                # Shouldn't happen due to fence range
                pass

    return result

