# Simplest possible fence rule: fill with 1s between markers, 4 at marker position

def apply_simple_fence(input_grid):
    result = [row[:] for row in input_grid]

    for r in range(len(input_grid)):
        row = input_grid[r]
        # Find first non-6 value
        first = next((c for c, v in enumerate(row) if v != 6), None)
        # Find last non-6 value
        last = next((c for c in range(len(row)-1, -1, -1) if row[c] != 6), None)

        if first is None or last is None:
            continue

        # Fence region: between first and last
        fence_start = first + 1
        fence_end = last

        # Look for special marker value (not 6, not 9) in the fence
        # The 8 in row 14 is special
        unique_pos = next((c for c in range(fence_start, fence_end) if row[c] != 6 and row[c] != 9), None)

        # If there's a unique value, apply fence with 4 at unique_pos
        if unique_pos is not None:
            for c in range(fence_start, fence_end):
                if c == unique_pos:
                    result[r][c] = 4
                else:
                    result[r][c] = 1
        elif unique_pos is None and fence_start < fence_end:
            # No unique value but there's a fence region - fill with 1s
            for c in range(fence_start, fence_end):
                result[r][c] = 1

    return result

